class TranslucentViewDetector : ResourceXmlDetector() {

    companion object {
        val ISSUE = Issue.create(
            id = "TranslucentOrientation",
            briefDescription = "Mixing screenOrientation and translucency",
            explanation = """
                Specifying a fixed screen orientation with a translucent theme isn't supported on apps with targetSdkVersion O or greater since there can be another activity visible behind your activity with a conflicting request.
                Devices running platform version O or greater will throw an exception if this state is detected.
            """.trimIndent(),
            category = Category.CORRECTNESS,
            priority = 6,
            severity = Severity.ERROR,
            implementation = Implementation(TranslucentViewDetector::class.java, Scope.MANIFEST_AND_RESOURCE_SCOPE)
        )

        private const val WINDOW_IS_TRANSLUCENT = "windowIsTranslucent"
        private const val TARGET_SDK_O = 26
        private val FIXED_ORIENTATIONS = setOf(
            "landscape", "portrait", "reverseLandscape", "reversePortrait",
            "sensorLandscape", "sensorPortrait", "userLandscape", "userPortrait", "locked"
        )
    }

    private var targetSdkVersion: Int = -1
    private var applicationTheme: String? = null
    private val activities = mutableListOf<ActivityInfo>()
    private val styles = mutableMapOf<String, StyleInfo>()

    data class ActivityInfo(val element: Element, val context: XmlContext, val theme: String?, val orientation: String?)
    data class StyleInfo(val parent: String?, val items: Map<String, String>)

    override fun getApplicableElements(): Collection<String> = listOf(
        "uses-sdk", "application", "activity", "style", "item"
    )

    override fun visitElement(context: XmlContext, element: Element) {
        when (element.tagName) {
            "uses-sdk" -> {
                val targetSdk = element.getAttributeNS(ANDROID_URI, ATTR_TARGET_SDK_VERSION)
                if (targetSdk.isNotBlank()) {
                    targetSdkVersion = targetSdk.toIntOrNull() ?: -1
                }
            }
            "application" -> {
                applicationTheme = element.getAttributeNS(ANDROID_URI, ATTR_THEME).resolveThemeRef()
            }
            "activity" -> {
                val theme = element.getAttributeNS(ANDROID_URI, ATTR_THEME).resolveThemeRef()
                val orientation = element.getAttributeNS(ANDROID_URI, ATTR_SCREEN_ORIENTATION)
                activities.add(ActivityInfo(element, context, theme, orientation))
            }
            "style" -> {
                val name = element.getAttribute(ATTR_NAME) // style name no namespace
                if (name.isNotBlank()) {
                    val parent = element.getAttribute(ATTR_PARENT).resolveThemeRef()
                    val items = mutableMapOf<String, String>()
                    var child = element.firstChild
                    while (child != null) {
                        if (child is Element && child.tagName == "item") {
                            val itemName = child.getAttributeNS(ANDROID_URI, ATTR_NAME)
                            val value = child.textContent?.trim() ?: ""
                            if (itemName.isNotBlank()) {
                                items[itemName] = value
                            }
                        }
                        child = child.nextSibling
                    }
                    styles[name] = StyleInfo(parent, items)
                }
            }
        }
    }

    override fun afterCheckEachProject(context: Context) {
        if (targetSdkVersion < TARGET_SDK_O) return
        for (activity in activities) {
            val orientation = activity.orientation ?: continue
            if (!isFixedOrientation(orientation)) continue
            val themeRef = activity.theme ?: applicationTheme ?: continue
            if (isTranslucent(themeRef)) {
                activity.context.report(
                    ISSUE,
                    activity.element,
                    activity.context.getLocation(activity.element),
                    "This activity's android:screenOrientation is fixed, but its theme is translucent; this is not supported on apps with targetSdkVersion >= O"
                )
            }
        }
    }

    private fun isFixedOrientation(orientation: String): Boolean {
        return FIXED_ORIENTATIONS.contains(orientation)
    }

    private fun isTranslucent(themeName: String): Boolean {
        var current: String? = themeName
        val seen = mutableSetOf<String>()
        while (current != null && seen.add(current)) {
            val style = styles[current] ?: return false
            val translucent = style.items[WINDOW_IS_TRANSLUCENT]
            if (translucent == "true" || translucent == "@bool/true" || translucent == "1") return true
            current = style.parent ?: deriveParentFromName(current)
        }
        return false
    }

    private fun deriveParentFromName(name: String): String? {
        // e.g. Theme.Translucent -> Theme
        val lastDot = name.lastIndexOf('.')
        return if (lastDot > 0) name.substring(0, lastDot) else null
    }

    private fun String.resolveThemeRef(): String? {
        return when {
            startsWith("@style/") -> substring(7)
            startsWith("@android:style/") -> substring("@android:style/".length)
            startsWith("?") -> null // attr refs not resolved
            else -> this
        }
    }
}

